import * as React from 'react'
import { cn } from '@/lib/utils'
import { useScrollIndicator } from '@/hooks/use-scroll-indicator'

export interface ScrollIndicatorProps {
  /** The scroll container to track. */
  scrollRef: React.RefObject<HTMLElement>
  /**
   * Pixels from the top of the positioned parent where the track starts.
   * Set it to the height of whatever floats over the scroller's top edge
   * (a frosted header) plus a small gap, so the thumb never runs behind it.
   */
  topOffset?: number
  /** Pixels from the bottom of the positioned parent. */
  bottomOffset?: number
  /**
   * Hide the indicator below the `md` breakpoint (default true) -- page-level
   * scrollers keep the platform's overlay scrollbars on mobile. Pass false
   * for surfaces that hide their native scrollbar at every size (drawers).
   */
  hideBelowMd?: boolean
  className?: string
}

/**
 * Custom auto-hiding scroll indicator. Renders inside a `relative` parent
 * that wraps (or contains) the scroll container, replacing a native
 * scrollbar that would otherwise run behind floating/sticky chrome. Pair it
 * with `.scrollbar-hide` on the scroll container. Purely visual:
 * pointer-events-none and hidden from assistive tech.
 */
export const ScrollIndicator = React.forwardRef<HTMLDivElement, ScrollIndicatorProps>(function ScrollIndicator({
  scrollRef,
  topOffset = 8,
  bottomOffset = 8,
  hideBelowMd = true,
  className,
}, ref) {
  const { thumbHeightPct, thumbTopPct, visible, hasOverflow } = useScrollIndicator(scrollRef)
  if (!hasOverflow) return null

  return (
    <div
      ref={ref}
      aria-hidden="true"
      className={cn(
        // Logical inset: inline-end puts the track on the left in RTL locales,
        // matching where native scrollbars sit there.
        'absolute end-1 z-40 pointer-events-none',
        hideBelowMd && 'hidden md:block',
        className,
      )}
      style={{ top: topOffset, bottom: bottomOffset, width: 6 }}
    >
      <div
        className="absolute end-0 w-1 rounded-full bg-[var(--color-neutral-400)] dark:bg-[var(--color-neutral-500)] transition-opacity duration-300"
        style={{
          height: `${thumbHeightPct}%`,
          top: `${thumbTopPct}%`,
          minHeight: 24,
          opacity: visible ? 0.6 : 0,
        }}
      />
    </div>
  )
})

ScrollIndicator.displayName = 'ScrollIndicator'
